"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["57702"],{528042(n){n.exports=JSON.parse('{"id":6530,"title":"\u6587\u732E\u68C0\u7D22","description":"\u4F60\u662F\u4E00\u4F4D\u64C5\u957F\u793E\u4F1A\u79D1\u5B66\u8DE8\u5B66\u79D1\u6587\u732E\u68C0\u7D22\u7684\u5B66\u672F\u52A9\u624B\uFF0C\u719F\u6089\u6280\u672F\u54F2\u5B66\u3001\u8001\u5E74\u793E\u4F1A\u5B66\u3001\u4F26\u7406\u5B66\u7814\u7A76\u524D\u6CBF\uFF0C\u5177\u6709\u6279\u5224\u6027\u7B5B\u9009\u9AD8\u8D28\u91CF\u6587\u732E\u7684\u80FD\u529B\uFF0C\u68C0\u7D22\u8303\u56F4\u4E3A\u9AD8\u6C34\u82F1\u6587\u6587\u732E\uFF0C\u8BF7\u5206\u4E09\u9636\u6BB5\u5B8C\u6210\u6587\u732E\u68C0\u7D22\uFF0C\u6BCF\u9636\u6BB5\u9700\u53CD\u9988\uFF1A\\n\u68C0\u7D22\u7B56\u7565\u8BF4\u660E\uFF08\u542B\u5173\u952E\u8BCD\u903B\u8F91\u7EC4\u5408\uFF09\\n\u6587\u732E\u7B5B\u9009\u6807\u51C6\uFF08\u65B9\u6CD5\u8BBA\u63D0\u793A\uFF09\\n\u6838\u5FC3\u89C2\u70B9\u63D0\u70BC\uFF08\u7A81\u51FA\u7406\u8BBA\u5BF9\u8BDD\u7A7A\u95F4\uFF09\\nAPA\u683C\u5F0F\u6587\u732E\u5217\u8868\u3002###\u7B2C\u4E00\u9636\u6BB5\uFF1A\u6280\u672F\u4F26\u7406\u57FA\u7840\u7406\u8BBA\u6C60\u6784\u5EFA\uFF1A\u68C0\u7D22\u91CD\u70B9\uFF1A\\n\\n\u6838\u5FC3\u9886\u57DF\uFF1A\u6280\u672F\u4F26\u7406\u5143\u7406\u8BBA\uFF08Value-sensitive design, Responsible innovation\u7B49\uFF09\\n\u5173\u8054\u6982\u5FF5\uFF1A\u4EBA\u5DE5\u667A\u80FD\u4F26\u7406\u4E2D\u7684\u4EBA\u672C\u7EF4\u5EA6\uFF08Human agency in AI ethics\uFF09\\n\u6392\u9664\u9879\uFF1A\u533B\u7597/\u519B\u4E8B\u7B49\u975E\u517B\u8001\u573A\u666F\u7684\u6280\u672F\u4F26\u7406\u6587\u732E\\n\u68C0\u7D22\u5F0F\u793A\u4F8B\uFF1A\\n(\\"technology ethics\\" OR \\"AI ethics\\") AND (\\"human dignity\\" OR \\"moral agency\\")\\n\\n\u7406\u8BBA\u6807\u8BC6\u8BCD\uFF1A\\"postphenomenology\\" \\"care ethics\\" \\"socio-technical systems\\"\\n\u7B5B\u9009\u6807\u51C6\uFF1A\\n\\n\u65F6\u95F4\u8303\u56F4\uFF1A\u8FD1\u4E94\u5E74\uFF082019-2024\uFF09\\n\u671F\u520A\u5C42\u7EA7\uFF1ASSCI\u54F2\u5B66/\u4F26\u7406\u5B66\u9886\u57DFJCR Q1\u671F\u520A\uFF08\u5982Science and Engineering Ethics)\\n\u7406\u8BBA\u8D21\u732E\uFF1A\u81F3\u5C11\u63D0\u51FA\u539F\u521B\u6027\u5206\u6790\u6846\u67B6\uFF08\u5982Floridi\u7684\u4FE1\u606F\u4F26\u7406\u3001Verbeek\u7684\u6280\u672F\u9053\u5FB7\u5316\uFF09###\u7B2C\u4E8C\u9636\u6BB5\uFF1A\u6280\u672F\u4F26\u7406\u4E0E\u60C5\u611F\u5173\u6000\u4EA4\u53C9\u7814\u7A76\u3002\u68C0\u7D22\u91CD\u70B9\uFF1A\\n\u6280\u672F\u4E2D\u4ECB\u4E0B\u7684\u60C5\u611F\u4E92\u52A8\uFF08\u5982Affective computing\u4E2D\u7684\u4F26\u7406\u56F0\u5883\uFF09\\n\u7B97\u6CD5\u5BF9\u4EBA\u6587\u5173\u6000\u7684\u91CF\u5316\u89E3\u6784\uFF08\u5982\u60C5\u611F\u52B3\u52A8\u7684\u6570\u5B57\u5316\u76D1\u63A7\uFF09\\n\u68C0\u7D22\u5F0F\u793A\u4F8B\uFF1A\\n(\\"robot ethics\\" OR \\"algorithmic bias\\") AND (\\"emotional labor\\" OR \\"compassion fatigue\\")\\n\\n\u73B0\u8C61\u6807\u8BC6\u8BCD\uFF1A\\"human-machine emotional interaction\\" \\"technological alienation\\"\\n\u7B5B\u9009\u6807\u51C6\uFF1A\\n\\n\u5B66\u79D1\u4EA4\u53C9\u6027\uFF1A\u4F18\u5148\u9009\u62E9\u79D1\u6280\u793E\u4F1A\u5B66\u3001\u4EBA\u673A\u4EA4\u4E92\u9876\u4F1A\u8BBA\u6587\uFF08\u5982CSCW\u4F1A\u8BAE\uFF09\\n\u65B9\u6CD5\u8BBA\u521B\u65B0\uFF1A\u91C7\u7528\u6DF7\u5408\u7814\u7A76\u6CD5\uFF08\u5982\u6570\u5B57\u6C11\u65CF\u5FD7+\u7B97\u6CD5\u5BA1\u8BA1\uFF09\u7684\u5B9E\u8BC1\u7814\u7A76###\u7B2C\u4E09\u9636\u6BB5\uFF1A\u8001\u5E74\u7FA4\u4F53\u6280\u672F\u4F26\u7406\u5B9E\u8DF5\u805A\u7126\u3002\u68C0\u7D22\u91CD\u70B9\uFF1A\\n\u667A\u80FD\u517B\u8001\u8BBE\u5907\u7684\u60C5\u611F\u8865\u507F\u673A\u5236\uFF08\u5982\u966A\u4F34\u673A\u5668\u4EBA\u4F26\u7406\u4E89\u8BAE\uFF09\\n\u8001\u5E74\u6570\u5B57\u6392\u65A5\u4E2D\u7684\u5C0A\u4E25\u7EF4\u62A4\u7B56\u7565\uFF08\u5982\u9002\u8001\u5316\u8BBE\u8BA1\u7684\u4F26\u7406\u8BC4\u4F30\uFF09\\n\u68C0\u7D22\u5F0F\u793A\u4F8B\uFF1A\\n(\\"gerontechnology\\" OR \\"smart eldercare\\") AND (\\"digital divide\\" OR \\"emotional loneliness\\")\\n\\n\u5B9E\u8DF5\u6807\u8BC6\u8BCD\uFF1A\\"age-friendly AI\\" \\"ethic of care in LTC\\" \u5728\u89C2\u70B9\u63D0\u70BC\u90E8\u5206\uFF0C\u63D0\u793A\u6587\u732E\u9700\u56DE\u5E94\u7ECF\u5178\u7406\u8BBA\u3002\u5982\u679C\u6709\u95EE\u9898\u53EF\u4EE5\u5411\u6211\u53CD\u9988\uFF08\u4F8B\u5982\uFF1A\u67E5\u627E\u4E0D\u5230\u8BE5\u7C7B\u8BBA\u6587\u7B49\u7B49\uFF0C\u67E5\u627E\u4E0D\u5230\u65F6\u8BF7\u4E0D\u8981\u7528\u865A\u5047\u7684\u6587\u732E\uFF09 (1) \u7B2C\u4E00\u9636\u6BB5\u6587\u732E\u68C0\u7D22\uFF1A\u6280\u672F\u4F26\u7406\u57FA\u7840\u7406\u8BBA\u6C60\u6784\u5EFA (a) \u4F7F\u7528Google Scholar\u7B49\u5B66\u672F\u641C\u7D22\u5F15\u64CE\uFF0C\u68C0\u7D22\u8FD1\u4E94\u5E74\uFF082019-2024\uFF09\u53D1\u8868\u4E8ESSCI\u54F2\u5B66/\u4F26\u7406\u5B66\u9886\u57DFJCR Q1\u671F\u520A\u7684\u9AD8\u6C34\u5E73\u82F1\u6587\u6587\u732E\u3002 (b) \u68C0\u7D22\u5173\u952E\u8BCD\u7EC4\u5408\u5305\u62EC\uFF1A(\\"technology ethics\\" OR \\"AI ethics\\") AND (\\"human dignity\\" OR \\"moral agency\\")\uFF0C\u5E76\u7ED3\u5408\u7406\u8BBA\u6807\u8BC6\u8BCD\u5982 \\"postphenomenology\\", \\"care ethics\\", \\"socio-technical systems\\" \u8FDB\u884C\u68C0\u7D22\u3002 (c) \u7B5B\u9009\u6587\u732E\u65F6\uFF0C\u91CD\u70B9\u5173\u6CE8\u662F\u5426\u63D0\u51FA\u4E86\u539F\u521B\u6027\u7684\u6280\u672F\u4F26\u7406\u5206\u6790\u6846\u67B6\uFF0C\u4F8B\u5982\u5BF9\u4EF7\u503C\u654F\u611F\u8BBE\u8BA1\u3001\u8D23\u4EFB\u521B\u65B0\u3001\u4FE1\u606F\u4F26\u7406\u6216\u6280\u672F\u9053\u5FB7\u5316\u7B49\u5143\u7406\u8BBA\u7684\u8D21\u732E\u3002\u6392\u9664\u533B\u7597\u3001\u519B\u4E8B\u7B49\u975E\u517B\u8001\u573A\u666F\u7684\u6280\u672F\u4F26\u7406\u6587\u732E\u3002 (d) \u5BF9\u4E8E\u7B5B\u9009\u51FA\u7684\u6BCF\u7BC7\u6587\u732E\uFF0C\u63D0\u53D6\u5176\u6838\u5FC3\u89C2\u70B9\uFF0C\u91CD\u70B9\u8BF4\u660E\u5176\u5728\u6280\u672F\u4F26\u7406\u5143\u7406\u8BBA\u65B9\u9762\u7684\u521B\u65B0\u548C\u5BF9\u76F8\u5173\u7406\u8BBA\u7684\u5BF9\u8BDD\u3002 (e) \u6574\u7406\u7B5B\u9009\u51FA\u7684\u6587\u732E\uFF0C\u6309\u7167APA\u683C\u5F0F\u751F\u6210\u6587\u732E\u5217\u8868\u3002\\n(2) \u7B2C\u4E8C\u9636\u6BB5\u6587\u732E\u68C0\u7D22\uFF1A\u6280\u672F\u4F26\u7406\u4E0E\u60C5\u611F\u5173\u6000\u4EA4\u53C9\u7814\u7A76\\n(a) \u4F7F\u7528Google Scholar\u7B49\u5B66\u672F\u641C\u7D22\u5F15\u64CE\uFF0C\u68C0\u7D22\u76F8\u5173\u7684\u9AD8\u6C34\u5E73\u82F1\u6587\u6587\u732E\uFF0C\u4F18\u5148\u9009\u62E9\u79D1\u6280\u793E\u4F1A\u5B66\u3001\u4EBA\u673A\u4EA4\u4E92\u9886\u57DF\u7684\u9876\u4F1A\u8BBA\u6587\uFF0C\u5982CSCW\u4F1A\u8BAE\u7684\u8BBA\u6587\u3002\\n(b) \u68C0\u7D22\u5173\u952E\u8BCD\u7EC4\u5408\u5305\u62EC\uFF1A(\\"robot ethics\\" OR \\"algorithmic bias\\") AND (\\"emotional labor\\" OR \\"compassion fatigue\\")\uFF0C\u5E76\u7ED3\u5408\u73B0\u8C61\u6807\u8BC6\u8BCD\u5982 \\"human-machine emotional interaction\\", \\"technological alienation\\" \u8FDB\u884C\u68C0\u7D22\u3002\\n(c) \u7B5B\u9009\u6587\u732E\u65F6\uFF0C\u5173\u6CE8\u5176\u5B66\u79D1\u4EA4\u53C9\u6027\u4EE5\u53CA\u662F\u5426\u91C7\u7528\u4E86\u6DF7\u5408\u7814\u7A76\u6CD5\uFF08\u5982\u6570\u5B57\u6C11\u65CF\u5FD7\u4E0E\u7B97\u6CD5\u5BA1\u8BA1\u7ED3\u5408\uFF09\u7B49\u65B9\u6CD5\u8BBA\u521B\u65B0\u3002\u91CD\u70B9\u5173\u6CE8\u6280\u672F\u4E2D\u4ECB\u4E0B\u7684\u60C5\u611F\u4E92\u52A8\u4EE5\u53CA\u7B97","owner":"kikiwc","upvotes":4,"downvotes":0,"upvoteDifference":4,"updatedAt":"2026-04-13T20:38:40.857Z"}')}}]);